// ONE URL PER LINE. Edit this list and nothing else.
const SITES = `
https://example.com
https://example.org
`;

return SITES.split('\n')
  .map(s => s.trim())
  .filter(s => s.length > 0)
  .map(url => ({ json: { url } }));

// Compare current status with the previous run and emit alerts ONLY on state changes.
// Requires the workflow to be Active (static data does not persist in manual runs).

const state = $getWorkflowStaticData('global');
if (!state.siteStatus) state.siteStatus = {};

const sites = $('Prepare Site URLs').all();
const results = $input.all();
const alerts = [];

for (let i = 0; i < results.length; i++) {
  const url = sites[i] ? sites[i].json.url : 'unknown';
  const r = results[i].json;

  const status = typeof r.statusCode === 'number' ? r.statusCode : 0;
  const failed = r.error !== undefined || status === 0 || status >= 500;
  const now = failed ? 'down' : 'up';
  const before = state.siteStatus[url] || 'up';

  if (now !== before) {
    const reason = r.error
      ? String(r.error.message || r.error).slice(0, 140)
      : `HTTP ${status}`;
    alerts.push({
      json: {
        text: now === 'down'
          ? `🔴 DOWN: ${url}\nReason: ${reason}\nTime: ${new Date().toISOString()}`
          : `🟢 RECOVERED: ${url}\nTime: ${new Date().toISOString()}`,
      },
    });
  }
  state.siteStatus[url] = now;
}

return alerts;

// Reuses the same list as the uptime loop - keeps config in ONE place.
const SITES = `
https://example.com
https://example.org
`;

return SITES.split('\n')
  .map(s => s.trim())
  .filter(s => s.length > 0)
  .map(url => ({ json: { domain: url.replace(/^https?:\/\//, '').replace(/\/.*$/, '') } }));

// Warn at 21 days before expiry, critical at 7. Also flags failed checks.
// Data source: Cert Spotter CT logs (free, no key). We take the NEWEST issued
// certificate per domain. If a renewed cert was issued but never deployed,
// the 5-minute uptime loop still catches the broken TLS as DOWN.
const WARN_DAYS = 21;
const CRITICAL_DAYS = 7;

const domains = $('Prepare Domain List').all();
const results = $input.all();
const alerts = [];
const now = Date.now();

for (let i = 0; i < results.length; i++) {
  const domain = domains[i] ? domains[i].json.domain : 'unknown';
  const r = results[i].json;

  const issuances = Array.isArray(r) ? r : (Array.isArray(r.data) ? r.data : null);
  if (r.error !== undefined || !issuances || issuances.length === 0) {
    alerts.push({ json: { text: `⚠️ SSL check failed for ${domain} - no certificate data returned. Check the site manually.` } });
    continue;
  }

  let latest = 0;
  for (const cert of issuances) {
    const t = Date.parse(cert.not_after);
    if (!Number.isNaN(t) && t > latest) latest = t;
  }
  if (latest === 0) continue;

  const days = Math.floor((latest - now) / 86400000);
  const till = new Date(latest).toISOString().slice(0, 10);

  if (days <= CRITICAL_DAYS) {
    alerts.push({ json: { text: `🚨 SSL CRITICAL: newest certificate for ${domain} expires in ${days} day(s) (${till}). Renew NOW.` } });
  } else if (days <= WARN_DAYS) {
    alerts.push({ json: { text: `⚠️ SSL warning: newest certificate for ${domain} expires in ${days} days (${till}).` } });
  }
}

return alerts;
